import React, { useState, useEffect, useRef } from "react";
import { createRoot } from "react-dom/client";
import { GoogleGenAI, Chat as GenAIChat, GenerateContentResponse } from "@google/genai";

// Declare globals for the CDN libraries
declare const marked: any;
declare const hljs: any;

// Initialize the API client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

type Message = {
  id: string;
  role: 'user' | 'model';
  text: string;
  isStreaming?: boolean;
};

const App = () => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'model',
      text: "Hello! I'm UCCAI. How can I help you today?"
    }
  ]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);

  // Ref to persist the chat session across renders
  const chatSessionRef = useRef<GenAIChat | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  // Initialize chat session
  useEffect(() => {
    try {
      chatSessionRef.current = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: "You are UCCAI, a helpful, intelligent, and precise AI assistant. You answer questions clearly and concisely. You format your answers using Markdown."
        }
      });
    } catch (error) {
      console.error("Failed to initialize chat:", error);
    }
  }, []);

  // Auto-scroll to bottom when messages change
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // Handle message sending
  const handleSend = async () => {
    if (!input.trim() || isLoading || !chatSessionRef.current) return;

    const userText = input.trim();
    setInput("");
    setIsLoading(true);

    // Add user message
    const userMsgId = Date.now().toString();
    setMessages(prev => [...prev, { id: userMsgId, role: 'user', text: userText }]);

    // Prepare placeholder for AI response
    const aiMsgId = (Date.now() + 1).toString();
    setMessages(prev => [...prev, { id: aiMsgId, role: 'model', text: "", isStreaming: true }]);

    try {
      // Send stream request
      const streamResult = await chatSessionRef.current.sendMessageStream({ message: userText });

      let fullText = "";

      for await (const chunk of streamResult) {
        const c = chunk as GenerateContentResponse;
        const chunkText = c.text || "";
        fullText += chunkText;

        // Update the last message with new content
        setMessages(prev => prev.map(msg => 
          msg.id === aiMsgId ? { ...msg, text: fullText } : msg
        ));
      }

      // Mark streaming as done
      setMessages(prev => prev.map(msg => 
        msg.id === aiMsgId ? { ...msg, isStreaming: false } : msg
      ));

    } catch (error) {
      console.error("Error sending message:", error);
      setMessages(prev => prev.map(msg => 
        msg.id === aiMsgId 
          ? { ...msg, text: "Sorry, I encountered an error processing your request.", isStreaming: false } 
          : msg
      ));
    } finally {
      setIsLoading(false);
      // Refocus input after sending (on desktop)
      if (window.innerWidth > 768) {
          inputRef.current?.focus();
      }
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  return (
    <div className="flex flex-col h-full bg-slate-900 font-sans">
      {/* Header */}
      <header className="flex-none p-4 bg-slate-950 border-b border-slate-800 shadow-sm z-10 flex items-center justify-between">
        <div className="flex items-center space-x-3">
          <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center text-white font-bold text-sm shadow-lg">
            U
          </div>
          <h1 className="text-xl font-bold tracking-tight text-slate-100">UCCAI</h1>
        </div>
        <div className="text-xs text-slate-500 font-medium px-2 py-1 bg-slate-900 rounded border border-slate-800">
          gemini-3-flash
        </div>
      </header>

      {/* Chat Area */}
      <main className="flex-1 overflow-y-auto p-4 sm:p-6 space-y-6 w-full max-w-4xl mx-auto">
        {messages.map((msg, idx) => (
          <MessageBubble key={msg.id} message={msg} />
        ))}
        {/* Invisible spacer for scrolling */}
        <div ref={messagesEndRef} className="h-4" />
      </main>

      {/* Input Area */}
      <footer className="flex-none p-4 bg-slate-950 border-t border-slate-800">
        <div className="max-w-4xl mx-auto relative">
          <div className="relative flex items-end gap-2 bg-slate-900 p-2 rounded-xl border border-slate-700 focus-within:border-blue-500 focus-within:ring-1 focus-within:ring-blue-500/50 transition-all shadow-lg">
            <textarea
              ref={inputRef}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder="Message UCCAI..."
              className="w-full bg-transparent text-slate-100 placeholder-slate-500 text-sm sm:text-base px-3 py-2 min-h-[44px] max-h-[160px] resize-none focus:outline-none"
              rows={1}
              style={{ height: 'auto', minHeight: '44px' }}
              onInput={(e) => {
                const target = e.target as HTMLTextAreaElement;
                target.style.height = 'auto';
                target.style.height = `${Math.min(target.scrollHeight, 160)}px`;
              }}
            />
            <button
              onClick={handleSend}
              disabled={!input.trim() || isLoading}
              className={`p-2 rounded-lg mb-0.5 transition-all duration-200 ${
                input.trim() && !isLoading
                  ? "bg-blue-600 hover:bg-blue-500 text-white shadow-md transform hover:scale-105"
                  : "bg-slate-800 text-slate-500 cursor-not-allowed"
              }`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5">
                <path d="M3.478 2.404a.75.75 0 0 0-.926.941l2.432 7.905H13.5a.75.75 0 0 1 0 1.5H4.984l-2.432 7.905a.75.75 0 0 0 .926.94 60.519 60.519 0 0 0 18.445-8.986.75.75 0 0 0 0-1.218A60.517 60.517 0 0 0 3.478 2.404Z" />
              </svg>
            </button>
          </div>
          <div className="text-center mt-2">
            <p className="text-[10px] text-slate-600">
              UCCAI may display inaccurate info, including about people, so double-check its responses.
            </p>
          </div>
        </div>
      </footer>
    </div>
  );
};

const MessageBubble = ({ message }: { message: Message }) => {
  const isUser = message.role === 'user';

  // Render markdown content safely
  const renderContent = () => {
    if (isUser) return <p className="whitespace-pre-wrap">{message.text}</p>;

    // If no text yet and streaming
    if (!message.text && message.isStreaming) {
      return (
        <div className="flex space-x-1.5 py-2">
          <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
          <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
          <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce"></div>
        </div>
      );
    }

    // Parse markdown
    const html = marked.parse(message.text);
    return <div className="prose prose-invert prose-sm max-w-none text-slate-200" dangerouslySetInnerHTML={{ __html: html }} />;
  };

  return (
    <div className={`flex w-full ${isUser ? 'justify-end' : 'justify-start'}`}>
      <div 
        className={`flex max-w-[85%] sm:max-w-[75%] gap-3 ${
          isUser ? 'flex-row-reverse' : 'flex-row'
        }`}
      >
        {/* Avatar */}
        <div className={`flex-none w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold shadow-md ${
          isUser 
            ? 'bg-slate-700 text-slate-300' 
            : 'bg-gradient-to-br from-blue-500 to-indigo-600 text-white'
        }`}>
          {isUser ? 'You' : 'U'}
        </div>

        {/* Bubble */}
        <div 
          className={`relative px-4 py-3 rounded-2xl shadow-sm overflow-hidden ${
            isUser 
              ? 'bg-slate-800 text-slate-100 rounded-tr-sm' 
              : 'bg-transparent text-slate-100 rounded-tl-sm border border-slate-800/50' // AI message is more subtle, let content pop
          }`}
        >
          {renderContent()}
        </div>
      </div>
    </div>
  );
};

// Initialize app
const root = createRoot(document.getElementById("root")!);
root.render(<App />);

