              : 'text-[#ececec] px-1'
          }`}
        >
          {!isUser && (
              <div className="text-xs font-bold mb-1 opacity-90">UCCAI</div>
          )}
          {renderContent()}
        </div>
      </div>
    </div>
  );
};

