                                    </a>
                                );
                            }
                            return null;
                        })}
                    </div>
                </div>
            )}
        </div>
    );
  };

  return (
    <div className={`flex w-full px-4 md:px-0 max-w-3xl mx-auto py-6 ${isUser ? '' : ''}`}>
      <div className={`flex w-full gap-4 ${isUser ? 'flex-row-reverse' : 'flex-row'}`}>
