        {/* Scrollable Area - Use Flex-1 and min-h-0 to allow scrolling inside flex item */}
        <div className="flex-1 overflow-y-auto w-full relative min-h-0 scroll-smooth pt-16 md:pt-14">
            {messages.length === 0 ? (
