const root = createRoot(document.getElementById("root")!);
root.render(<App />);

import React, { useState, useEffect, useRef } from "react";
import { createRoot } from "react-dom/client";
import { GoogleGenAI, Chat as GenAIChat, GenerateContentResponse } from "@google/genai";

// Declare globals for the CDN libraries
declare const marked: any;
declare const hljs: any;

// Initialize the API client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

type Message = {
  id: string;
  role: 'user' | 'model';
  text: string;
  isStreaming?: boolean;
  images?: string[]; 
};

type Attachment = {
  file: File;
  previewUrl: string;
};

type User = {
    fullName: string;
    username: string;
    email: string;
    phoneNumber: string;
    password?: string;
};

// --- Auth Components ---

const AuthScreen = ({ onLogin }: { onLogin: (user: User) => void }) => {
    const [isLogin, setIsLogin] = useState(true);
    const [formData, setFormData] = useState({
        fullName: "",
        username: "",
        email: "",
        phoneNumber: "",
        password: "",
        confirmPassword: ""
    });
    const [error, setError] = useState("");

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
        setError("");
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setError("");

        if (isLogin) {
            // Login Logic
            const storedUsersStr = localStorage.getItem("uccai_users");
            const users: User[] = storedUsersStr ? JSON.parse(storedUsersStr) : [];

            // Allow login with username OR email using the username field input
            const identifier = formData.username;
            const user = users.find(u => 
                (u.username === identifier || u.email === identifier) && 
                u.password === formData.password
            );

            if (user) {
                localStorage.setItem("uccai_currentUser", JSON.stringify(user));
                onLogin(user);
            } else {
                setError("Invalid credentials.");
            }
        } else {
            // Signup Logic
            if (!formData.fullName || !formData.username || !formData.email || !formData.phoneNumber || !formData.password) {
                setError("All fields are required.");
                return;
            }
            if (formData.password !== formData.confirmPassword) {
                setError("Passwords do not match.");
                return;
            }

            const storedUsersStr = localStorage.getItem("uccai_users");
            const users: User[] = storedUsersStr ? JSON.parse(storedUsersStr) : [];

            if (users.find(u => u.username === formData.username)) {
                setError("Username already taken.");
                return;
            }
            if (users.find(u => u.email === formData.email)) {
                setError("Email already registered.");
                return;
            }

            const newUser: User = {
                fullName: formData.fullName,
                username: formData.username,
                email: formData.email,
                phoneNumber: formData.phoneNumber,
                password: formData.password
            };

            users.push(newUser);
            localStorage.setItem("uccai_users", JSON.stringify(users));
            localStorage.setItem("uccai_currentUser", JSON.stringify(newUser));
            onLogin(newUser);
        }
    };

    return (
        <div className="min-h-full w-full bg-[#171717] flex items-center justify-center p-4">
            <div className="w-full max-w-md bg-[#212121] rounded-2xl shadow-2xl p-8 border border-white/5">
                <div className="flex flex-col items-center mb-8">
                    <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center mb-4 shadow-lg">
                        <svg className="w-6 h-6 text-black" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4"/><path d="M12 8h.01"/></svg>
                    </div>
                    <h1 className="text-2xl font-bold text-white tracking-tight">
                        {isLogin ? "Welcome back" : "Create your account"}
                    </h1>
                    <p className="text-gray-400 text-sm mt-2">
                        {isLogin ? "Sign in to access your AI assistant" : "Join UCCAI for smart assistance"}
                    </p>
                </div>

                <form onSubmit={handleSubmit} className="space-y-4">
                    {!isLogin && (
                        <div>
                            <label className="block text-xs font-medium text-gray-400 mb-1 ml-1">Full Name</label>
                            <input
                                name="fullName"
                                type="text"
                                placeholder="John Doe"
