                    <p className="text-gray-400 text-sm mt-2">
                        {isLogin ? "Sign in to access your AI assistant" : "Join UCCAI for smart assistance"}
                    </p>
                </div>

                <form onSubmit={handleSubmit} className="space-y-4">
                    {!isLogin && (
                        <div>
                            <label className="block text-xs font-medium text-gray-400 mb-1 ml-1">Full Name</label>
                            <input
                                name="fullName"
                                type="text"
                                placeholder="John Doe"
                                value={formData.fullName}
                                onChange={handleChange}
                                className="w-full bg-[#2f2f2f] text-white rounded-xl px-4 py-3 text-sm border border-transparent focus:border-blue-500 focus:outline-none transition-all placeholder-gray-500"
                            />
                        </div>
                    )}

                    <div>
                        <label className="block text-xs font-medium text-gray-400 mb-1 ml-1">
                            {isLogin ? "Username or Email" : "Username"}
                        </label>
                        <input
                            name="username"
                            type="text"
                            placeholder={isLogin ? "username or email" : "johndoe"}
                            value={formData.username}
                            onChange={handleChange}
                            className="w-full bg-[#2f2f2f] text-white rounded-xl px-4 py-3 text-sm border border-transparent focus:border-blue-500 focus:outline-none transition-all placeholder-gray-500"
                        />
                    </div>

                    {!isLogin && (
                        <div>
                            <label className="block text-xs font-medium text-gray-400 mb-1 ml-1">Email Address</label>
                            <input
                                name="email"
                                type="email"
                                placeholder="john@example.com"
                                value={formData.email}
                                onChange={handleChange}
                                className="w-full bg-[#2f2f2f] text-white rounded-xl px-4 py-3 text-sm border border-transparent focus:border-blue-500 focus:outline-none transition-all placeholder-gray-500"
                            />
                        </div>
                    )}

                    {!isLogin && (
