// --- App Orchestration ---

const App = () => {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    const storedUser = localStorage.getItem("uccai_currentUser");
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
  }, []);

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
  };

  const handleLogout = () => {
    localStorage.removeItem("uccai_currentUser");
    setUser(null);
  };

  if (!user) {
    return <AuthScreen onLogin={handleLogin} />;
  }

  return <ChatInterface user={user} onLogout={handleLogout} />;
};

// Initialize app
const root = createRoot(document.getElementById("root")!);
root.render(<App />);

import React, { useState, useEffect, useRef } from "react";
import { createRoot } from "react-dom/client";
import { GoogleGenAI, Chat as GenAIChat, GenerateContentResponse } from "@google/genai";

// Declare globals for the CDN libraries
declare const marked: any;
declare const hljs: any;

// Initialize the API client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

type Message = {
  id: string;
  role: 'user' | 'model';
  text: string;
  isStreaming?: boolean;
  images?: string[]; 
};

type Attachment = {
  file: File;
  previewUrl: string;
};

type User = {
    fullName: string;
    username: string;
    email: string;
    phoneNumber: string;
    password?: string;
};

// --- Auth Components ---

const AuthScreen = ({ onLogin }: { onLogin: (user: User) => void }) => {
    const [isLogin, setIsLogin] = useState(true);
    const [formData, setFormData] = useState({
        fullName: "",
        username: "",
        email: "",
        phoneNumber: "",
        password: "",
        confirmPassword: ""
    });
    const [error, setError] = useState("");

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
        setError("");
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setError("");

        if (isLogin) {
            // Login Logic
            const storedUsersStr = localStorage.getItem("uccai_users");
            const users: User[] = storedUsersStr ? JSON.parse(storedUsersStr) : [];

            // Allow login with username OR email using the username field input
            const identifier = formData.username;
            const user = users.find(u => 
                (u.username === identifier || u.email === identifier) && 
                u.password === formData.password
            );

            if (user) {
                localStorage.setItem("uccai_currentUser", JSON.stringify(user));
                onLogin(user);
            } else {
                setError("Invalid credentials.");
            }
        } else {
            // Signup Logic
            if (!formData.fullName || !formData.username || !formData.email || !formData.phoneNumber || !formData.password) {
                setError("All fields are required.");
                return;
            }
            if (formData.password !== formData.confirmPassword) {
                setError("Passwords do not match.");
                return;
            }

            const storedUsersStr = localStorage.getItem("uccai_users");
            const users: User[] = storedUsersStr ? JSON.parse(storedUsersStr) : [];

            if (users.find(u => u.username === formData.username)) {
                setError("Username already taken.");
                return;
            }
            if (users.find(u => u.email === formData.email)) {
                setError("Email already registered.");
                return;
            }

            const newUser: User = {
                fullName: formData.fullName,
                username: formData.username,
                email: formData.email,
                phoneNumber: formData.phoneNumber,
                password: formData.password
            };

            users.push(newUser);
            localStorage.setItem("uccai_users", JSON.stringify(users));
            localStorage.setItem("uccai_currentUser", JSON.stringify(newUser));
            onLogin(newUser);
        }
    };

    return (
        <div className="min-h-full w-full bg-[#171717] flex items-center justify-center p-4">
            <div className="w-full max-w-md bg-[#212121] rounded-2xl shadow-2xl p-8 border border-white/5">
                <div className="flex flex-col items-center mb-8">
                    <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center mb-4 shadow-lg">
                        <svg className="w-6 h-6 text-black" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4"/><path d="M12 8h.01"/></svg>
                    </div>
                    <h1 className="text-2xl font-bold text-white tracking-tight">
                        {isLogin ? "Welcome back" : "Create your account"}
                    </h1>
                    <p className="text-gray-400 text-sm mt-2">
                        {isLogin ? "Sign in to access your AI assistant" : "Join UCCAI for smart assistance"}
                    </p>
                </div>

                <form onSubmit={handleSubmit} className="space-y-4">
                    {!isLogin && (
                        <div>
                            <label className="block text-xs font-medium text-gray-400 mb-1 ml-1">Full Name</label>
                            <input
                                name="fullName"
                                type="text"
                                placeholder="John Doe"
                                value={formData.fullName}
                                onChange={handleChange}
                                className="w-full bg-[#2f2f2f] text-white rounded-xl px-4 py-3 text-sm border border-transparent focus:border-blue-500 focus:outline-none transition-all placeholder-gray-500"
                            />
                        </div>
                    )}

                    <div>
                        <label className="block text-xs font-medium text-gray-400 mb-1 ml-1">
                            {isLogin ? "Username or Email" : "Username"}
                        </label>
                        <input
                            name="username"
                            type="text"
                            placeholder={isLogin ? "username or email" : "johndoe"}
                            value={formData.username}
                            onChange={handleChange}
                            className="w-full bg-[#2f2f2f] text-white rounded-xl px-4 py-3 text-sm border border-transparent focus:border-blue-500 focus:outline-none transition-all placeholder-gray-500"
                        />
                    </div>

                    {!isLogin && (
                        <div>
                            <label className="block text-xs font-medium text-gray-400 mb-1 ml-1">Email Address</label>
                            <input
                                name="email"
                                type="email"
                                placeholder="john@example.com"
                                value={formData.email}
                                onChange={handleChange}
                                className="w-full bg-[#2f2f2f] text-white rounded-xl px-4 py-3 text-sm border border-transparent focus:border-blue-500 focus:outline-none transition-all placeholder-gray-500"
                            />
                        </div>
                    )}

                    {!isLogin && (
                         <div>
                            <label className="block text-xs font-medium text-gray-400 mb-1 ml-1">Phone Number</label>
                            <input
                                name="phoneNumber"
                                type="tel"
                                placeholder="+1 (555) 000-0000"
                                value={formData.phoneNumber}
                                onChange={handleChange}
                                className="w-full bg-[#2f2f2f] text-white rounded-xl px-4 py-3 text-sm border border-transparent focus:border-blue-500 focus:outline-none transition-all placeholder-gray-500"
                            />
                        </div>
                    )}

                    <div>
                         <label className="block text-xs font-medium text-gray-400 mb-1 ml-1">Password</label>
                        <input
                            name="password"
                            type="password"
                            placeholder="••••••••"
                            value={formData.password}
                            onChange={handleChange}
                            className="w-full bg-[#2f2f2f] text-white rounded-xl px-4 py-3 text-sm border border-transparent focus:border-blue-500 focus:outline-none transition-all placeholder-gray-500"
                        />
                    </div>

                    {!isLogin && (
                        <div>
                             <label className="block text-xs font-medium text-gray-400 mb-1 ml-1">Confirm Password</label>
                            <input
                                name="confirmPassword"
                                type="password"
                                placeholder="••••••••"
                                value={formData.confirmPassword}
                                onChange={handleChange}
                                className="w-full bg-[#2f2f2f] text-white rounded-xl px-4 py-3 text-sm border border-transparent focus:border-blue-500 focus:outline-none transition-all placeholder-gray-500"
                            />
                        </div>
                    )}

                    {error && (
                        <div className="text-red-400 text-xs bg-red-400/10 p-3 rounded-lg flex items-center gap-2">
                             <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
                             {error}
                        </div>
                    )}

                    <button
                        type="submit"
                        className="w-full bg-white text-black font-semibold rounded-xl px-4 py-3 mt-4 hover:bg-gray-200 transition-colors shadow-lg"
                    >
                        {isLogin ? "Sign In" : "Create Account"}
                    </button>
                </form>

                <div className="mt-6 text-center">
                    <p className="text-gray-400 text-sm">
                        {isLogin ? "Don't have an account? " : "Already have an account? "}
                        <button
                            onClick={() => {
                                setIsLogin(!isLogin);
                                setError("");
                                setFormData({ fullName: "", username: "", email: "", phoneNumber: "", password: "", confirmPassword: "" });
                            }}
                            className="text-white font-medium hover:underline focus:outline-none"
                        >
                            {isLogin ? "Sign up" : "Log in"}
                        </button>
                    </p>
                </div>
            </div>
        </div>
    );
};

